# 무안행복중 중1 통계 1 · 2차시 차시팩 v4 (2026-11-23 · 📚 차시팩 #1)
#   선생님: 「학습지를 보고 문제를 풀 수 있게 · 문제의 변형은 같은 문항의 학습지 도수분포표를 다르게 해석하는 문항으로」
#   → 표 · 줄기와 잎 · 히스토그램은 학습지(+ 몬스터 칸 학습지 그림)를 보고 풂 · 문항 글 첫머리 = 어느 학습지 자료인지 + 기준 정보
#   → 판 0 = 학습지 물음 그대로 · 판 1 ~ 6 = 숫자를 바꾸지 않고 같은 자료에서 다른 것을 물음(한 몬스터 21물음 모두 다름)
#   (옛 v4 초안 = 자료를 글로 옮긴 판 · git 기록에 있음)
#   쓰는 법: python3 gen_v4.py <v3 팩 1.json> <v3 팩 2.json> <출력 폴더> → 검산 = verify_v4.py (따로 적은 자료로 다시 풂)
import json, sys, copy, os
P1, P2, OUT = sys.argv[1:4]
def it(t, q, a, ch=None, sol=''):
    assert sol and len(sol) <= 90, (q, sol)
    return {'type': t, 'q': q, 'a': str(a), 'ch': ch or [], 'sol': sol}
def C(head, q, ch, ans, sol): assert ch.count(ans) == 1, (q, ch); return it('choice', f'{head}\n{q}' if head else q, ch.index(ans), ch, sol)
def N(head, q, a, sol): assert 0 <= a <= 99, (q, a); return it('number', f'{head}\n{q}', a, sol=sol)
def O(q, a, sol): return it('ox', q, a, sol=sol)
class T:   # 도수분포표 (계급 시작 · 크기 · 도수)
    def __init__(s, lo, w, f): s.lo, s.w, s.f = lo, w, f
    def b(s, i): return s.lo + i * s.w
    def rng(s, a, c): return sum(n for i, n in enumerate(s.f) if a <= s.b(i) and s.b(i + 1) <= c)
    def ge(s, a): return s.rng(a, 10 ** 9)
    def lt(s, a): return s.rng(-10 ** 9, a)
    def rank(s, r, big=True):   # r 번째로 큰(작은) 계급 번호 · 같은 도수가 있으면 멈춤
        o = sorted(set(s.f), reverse=big); assert s.f.count(o[r - 1]) == 1; return s.f.index(o[r - 1])
    def add(s, ids): return ' + '.join(str(s.f[i]) for i in ids)
    def ids(s, a, c): return [i for i in range(len(s.f)) if a <= s.b(i) and s.b(i + 1) <= c]

