def build(src, mons, boss, links):
    d = json.load(open(src, encoding='utf8')); v3 = copy.deepcopy(d)
    for mid, vers in mons.items():
        for a, b in zip(vers[0], v3['mons'][mid]['vers'][0]):   # 판 0 = 학습지 물음 · 정답 · 보기 그대로
            assert a['a'] == b['a'] and a['ch'] == b['ch'] and a['type'] == b['type'] and a['q'].split('\n')[-1] == b['q'].split('] ')[-1], (mid, a['q'][-60:], b['q'])
        d['mons'][mid]['vers'] = vers
    for a, b in zip(boss[0], v3['boss']['vers'][0]): assert a['a'] == b['a'] and a['ch'] == b['ch'] and a['type'] == b['type'], (a['q'][-60:], b['q'])
    d['boss']['vers'] = boss; d['boss']['links'] = links
    for m in list(d['mons'].values()) + [d['boss']]:
        assert len(m['vers']) == 7
        for v in m['vers']: assert [x['type'] for x in v] == [x['type'] for x in m['vers'][0]]
        qs = [x['q'] for v in m['vers'] for x in v if x['type'] != 'ox']
        assert len(qs) == len(set(qs)), [q for q in qs if qs.count(q) > 1]     # 판끼리 같은 물음 없음
        oxs = [x['q'] for v in m['vers'] for x in v if x['type'] == 'ox']
        for v in m['vers']: assert len({x['q'] for x in v}) == len(v)
    return d
p1 = build(P1, {'m1': m11, 'm2': m12, 'm3': m13}, b1, ['m1', 'm1', 'm1', '', ''])
p2 = build(P2, {'m1': m21, 'm2': m22, 'm3': m23}, b2, ['m3', 'm3', '', '', ''])
